<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import { clone, id, domainData, collectKnowledge, type Kind, type Task } from '../model/domain';
import type { ImportDraft } from '../model/imports';
import { storageError } from '../model/imports';
import { initializeReview, contentReviewed, contentSignature, reviewIssues, changed, blankBlock, newPart, newItem, moveBlocks, splitSolution, targetRows, definitions, saveReviewMapping, mappingConfirmed, roles, blockNames, type ReviewBlock, type ReviewPart, type PartRole } from '../model/review-content';
import WorkbenchDialog from './WorkbenchDialog.vue';
import ReviewSource from './ReviewSource.vue';
import ReviewBlockView from './ReviewBlockView.vue';
import ReviewBlockEditor from './ReviewBlockEditor.vue';
import TaskWorkspace from './domain/TaskWorkspace.vue';
import MethodWorkspace from './domain/MethodWorkspace.vue';
import KnowledgeWorkspace from './domain/KnowledgeWorkspace.vue';
const props=defineProps<{draft:ImportDraft;mode:string}>();
const emit=defineEmits<{stage:[value:'semantic'|'fusion']}>();
const state=initializeReview(props.draft);
const routeItem=new URLSearchParams(location.hash.split('?')[1]||'').get('item');
if(routeItem&&state.items.some(i=>i.id===routeItem)){state.selected=routeItem;props.draft.workspace='semantic';}
const item=computed(()=>state.items.find(i=>i.id===state.selected)||state.items[0]);
const sourcePage=ref(item.value?.parts[0]?.blocks[0]?.page||state.pages[0]||49),sourceRect=ref([0,0,1,1]);
const selectedBlock=ref(''),error=ref(''),notice=ref(''),filter=ref(''),checked=ref(false);
const chapters=computed(()=>[...new Set(state.items.map(i=>i.chapter))]);
const editor=ref<{block:ReviewBlock;partId:string;isNew:boolean;newPart?:ReviewPart}|null>(null);
const dialog=ref<''|'add'|'move'|'split'|'rename'|'newItem'|'preview'|'history'|'mapping'>('');
const from=ref(''),to=ref(''),chosen=ref<string[]>([]),name=ref(''),type=ref<ReviewBlock['type']>('text'),newRole=ref<PartRole>('question'),newKind=ref<'task'|'knowledge'>('task'),chapter=ref('');
const matchPart=ref(''),selectedDefinition=ref(''),query=ref('');
const modelEditor=ref<{kind:Kind;id:string;tab:string}|null>(null);
const activeMatch=computed(()=>item.value?.parts.find(p=>p.id===matchPart.value));
const currentTask=computed(()=>domainData.tasks.find(t=>t.id===item.value?.parts.find(p=>p.role==='question')?.templateId&&t.domainId===props.draft.book.domainId));
const modelOptions=computed(()=>activeMatch.value?definitions(activeMatch.value.role,props.draft.book.domainId).filter(d=>d.name.includes(query.value)&&(activeMatch.value!.role!=='solution'||currentTask.value?.methods.includes(d.id))):[]);
const definition=computed(()=>modelOptions.value.find(d=>d.id===selectedDefinition.value));
const solutions=computed(()=>item.value?.parts.filter(p=>p.role==='solution')||[]);
const selectedPart=computed(()=>item.value?.parts.find(p=>p.id===from.value));
function select(key:string){state.selected=key;checked.value=false;error.value='';notice.value='';modelEditor.value=null;const b=item.value?.parts.flatMap(p=>p.blocks)[0];if(b)focus(b);nextTick(()=>document.querySelector('.page-container')?.scrollTo({top:0}));}
function focus(b:ReviewBlock){sourcePage.value=b.page;sourceRect.value=[...b.rect];selectedBlock.value=b.id;}
function modified(before:ReviewPart[],action:string){changed(item.value,before,action);checked.value=false;notice.value='修改已保存到本浏览器；本项需要重新核对。';error.value='';}
function edit(b:ReviewBlock,p:ReviewPart){focus(b);editor.value={block:clone(b),partId:p.id,isNew:false};}
function saveBlock(b:ReviewBlock){const p=item.value.parts.find(p=>p.id===editor.value?.partId)||editor.value?.newPart;if(!p)return;const before=clone(item.value.parts);if(editor.value?.newPart)item.value.parts.push(p);const index=p.blocks.findIndex(x=>x.id===b.id);if(index>=0)p.blocks[index]=b;else p.blocks.push(b);modified(before,'保存'+blockNames[b.type]);editor.value=null;focus(b);}
function add(part?:ReviewPart){to.value=part?.id||item.value.parts[0].id;type.value='text';newRole.value='solution';name.value='';dialog.value='add';}
function createBlock(){let p=item.value.parts.find(p=>p.id===to.value);if(to.value==='new')p=newPart(newRole.value,name.value.trim()||roles[newRole.value]);if(!p)return;editor.value={partId:p.id,isNew:true,newPart:to.value==='new'?p:undefined,block:blankBlock(type.value,sourcePage.value,sourceRect.value)};dialog.value='';}
function remove(b:ReviewBlock,p:ReviewPart){if(!window.confirm('移除这块提取内容？原件及修改记录保留。'))return;const before=clone(item.value.parts);p.blocks=p.blocks.filter(x=>x.id!==b.id);modified(before,'移除提取内容');}
function removePart(p:ReviewPart){if(!window.confirm('移除“'+p.name+'”？原始提取和修改记录保留。'))return;const before=clone(item.value.parts);item.value.parts=item.value.parts.filter(x=>x.id!==p.id);modified(before,'移除'+p.name);}
function reorder(p:ReviewPart,index:number){const before=clone(item.value.parts);[p.blocks[index-1],p.blocks[index]]=[p.blocks[index],p.blocks[index-1]];modified(before,'调整内容顺序');}
function copyChart(b:ReviewBlock,p:ReviewPart){const value=clone(b);value.id=id('CONTENT');value.chart.title+='（副本）';editor.value={block:value,partId:p.id,isNew:true};}
function move(b:ReviewBlock,p:ReviewPart){from.value=p.id;chosen.value=[b.id];to.value='';newRole.value='note';name.value='';dialog.value='move';error.value='';}
function applyMove(){try{const before=clone(item.value.parts);if(to.value==='new'){const p=newPart(newRole.value,name.value.trim()||roles[newRole.value]);item.value.parts.push(p);to.value=p.id;}moveBlocks(item.value,from.value,to.value,chosen.value);item.value.history[0].before=before;checked.value=false;dialog.value='';notice.value='内容已移动；原出处保留。';}catch(e){error.value=String(e);}}
function split(p:ReviewPart){from.value=p.id;chosen.value=[];name.value='教材解法 '+(solutions.value.length+1);dialog.value='split';error.value='';}
function applySplit(){try{splitSolution(item.value,from.value,chosen.value,name.value);checked.value=false;dialog.value='';notice.value='已拆成两份解法，仍属于同一道题。';}catch(e){error.value=String(e);}}
function rename(p:ReviewPart){from.value=p.id;name.value=p.name;dialog.value='rename';}
function applyRename(){if(!name.value.trim()||!selectedPart.value)return;const before=clone(item.value.parts);selectedPart.value.name=name.value.trim();modified(before,'修改内容名称');dialog.value='';}
function addItem(){name.value='';newKind.value='task';chapter.value=item.value?.chapter||chapters.value[0]||'未分章';dialog.value='newItem';}
function createItem(){if(!name.value.trim()||!chapter.value.trim())return;const value=newItem(name.value,chapter.value,newKind.value);state.items.push(value);state.selected=value.id;dialog.value='';checked.value=false;add(value.parts[0]);}
function confirmContent(){const problems=reviewIssues(item.value,state.pages);if(!checked.value)problems.push('请先确认已对照原页核对完整内容');if(problems.length){error.value=[...new Set(problems)].join('；');return;}item.value.reviewed=contentSignature(item.value);notice.value='本项内容已核对。接下来确认领域匹配。';error.value='';emit('stage','fusion');}
function suggested(p:ReviewPart){const taskIds:Record<string,string>={C02:'TT-CHAIN',C03:'TT-ERROR',C05:'TT-CHART',C06:'TT-SHAPE'};const suffix=p.role==='question'?taskIds[item.value.id]:p.role==='solution'&&item.value.id==='C02'?(solutions.value.indexOf(p)===0?'ST-TWO':'ST-COMBINE'):'';const key=props.draft.book.domainId+'-REVIEW-'+suffix;return definitions(p.role,props.draft.book.domainId).find(d=>d.id===key);}
function match(p:ReviewPart){matchPart.value=p.id;selectedDefinition.value=p.templateId||suggested(p)?.id||'';query.value='';dialog.value='mapping';error.value='';}
function useDefinition(){const p=activeMatch.value;if(!p||!definition.value)return;if(p.role==='question'&&p.templateId!==definition.value.id){item.value.parts.filter(s=>s.role==='solution').forEach(s=>s.templateId='');p.parameters={};}p.templateId=definition.value.id;p.reason='管理员对照定义与教材内容确认（mock）';item.value.matched='';dialog.value='';notice.value='已选择定义，请核对参数和其他关联后保存。';}
function openModel(kind:Kind,objectId='new',tab='definition'){modelEditor.value={kind,id:objectId,tab};dialog.value='';}
function modelSaved(key:string){const kind=modelEditor.value!.kind;modelEditor.value={kind,id:key,tab:modelEditor.value!.tab};notice.value='定义已直接保存到当前领域。返回匹配后选用；不会自动更改教材内容。';}
function saveMatch(){const errors=saveReviewMapping(item.value,props.draft.book.domainId,props.draft.id);error.value=errors.join('；');if(!errors.length)notice.value='模型关联已保存，编号与来源由程序维护。本项尚未应用给学生。';}
function saveDraft(){notice.value=storageError.value||'草稿已保存在本浏览器，稍后可从教材列表继续。';}
const mappedName=(p:ReviewPart)=>definitions(p.role,props.draft.book.domainId).find(d=>d.id===p.templateId)?.name||'尚未选择';
const kindFor=(p:ReviewPart):Kind=>p.role==='question'?'task':p.role==='solution'?'solution':'kc';
</script>
<template><section class="content-review-workspace">
  <header class="review-header"><div><h3>{{mode==='fusion'?'确认领域匹配':'对照原件，核对提取内容'}}</h3><p class="muted">{{draft.reviewExamples?'四例交互走查 · 原页真实，提取与匹配为固定mock':'原件与提取内容在此核对；原有草稿记录保留'}} · 不运行真实LLM</p></div><button class="btn" @click="saveDraft">保存草稿</button></header>
  <p v-if="error" class="callout danger" role="alert">{{error}}</p><p v-if="notice" class="saved-note" role="status">{{notice}}</p><p v-if="storageError" class="callout danger" role="alert">{{storageError}}</p>
  <div v-if="item" class="review-layout">
    <aside class="review-nav panel"><h3>章节与内容</h3><label class="sr-only" for="review-filter">查找内容</label><input id="review-filter" v-model="filter" placeholder="查找内容"/><section v-for="ch in chapters" :key="ch"><h4>{{ch}}</h4><button v-for="i in state.items.filter(i=>i.chapter===ch&&i.title.includes(filter))" :key="i.id" class="review-item" :class="{active:item.id===i.id}" @click="select(i.id)"><span>{{i.title}}</span><small>{{mappingConfirmed(i,draft.book.domainId)?'模型已关联':contentReviewed(i)?'内容已核对':'待核对'}}</small></button></section><button class="btn" @click="addItem">添加内容项</button><p class="muted">请逐页检查。未报疑点不代表没有遗漏。</p></aside>
    <section class="panel review-original"><h3>原始书页</h3><ReviewSource :page="sourcePage" :pages="state.pages" :rect="sourceRect" editable @change="(page,rect)=>{sourcePage=page;sourceRect=rect}"/><p class="muted">可翻看本次导入的全部 {{state.pages.length}} 页，包括尚未提取内容的页。</p></section>
    <section class="panel review-result"><div class="row-between"><div><h3>{{item.title}}</h3><span class="badge">{{contentReviewed(item)?'内容已核对':'待核对'}}</span></div><button class="text-link" @click="dialog='history'">修改记录</button></div>
      <template v-if="mode!=='fusion'">
        <p v-if="item.sourceNote" class="muted">{{item.sourceNote}}</p>
        <section v-for="part in item.parts" :key="part.id" class="review-part" :data-role="part.role">
          <details v-if="part.role==='answer'||part.role==='note'"><summary>{{part.name}}（不进入学生题面）</summary><div v-for="b in part.blocks" :key="b.id" class="review-content" :class="{selected:selectedBlock===b.id}" @click="focus(b)"><ReviewBlockView :block="b"/><div class="content-actions"><small>第 {{b.page}} 页</small><button class="text-link" @click.stop="edit(b,part)">编辑</button><button class="text-link" @click.stop="move(b,part)">移动到…</button><button class="text-link" @click.stop="remove(b,part)">移除</button></div></div><button class="text-link" @click="add(part)">添加内容</button></details>
          <template v-else><div class="part-heading"><h4>{{part.name}}</h4><div class="button-row"><button v-if="part.role==='solution'" class="text-link" @click="split(part)">拆分解法</button><button class="text-link" @click="rename(part)">改名</button><button v-if="part.role==='solution'" class="text-link" @click="removePart(part)">移除解法</button></div></div>
          <p v-if="!part.blocks.length" class="muted">尚无内容。可从原页补入。</p>
          <div v-for="(b,index) in part.blocks" :key="b.id" class="review-content" :class="{selected:selectedBlock===b.id}" :data-block="b.type" @click="focus(b)"><ReviewBlockView :block="b"/><div class="content-actions"><small>第 {{b.page}} 页</small><button class="text-link" @click.stop="edit(b,part)">编辑</button><button class="text-link" @click.stop="move(b,part)">移动到…</button><button v-if="index>0" class="text-link" @click.stop="reorder(part,index)">上移</button><button v-if="b.type==='chart'" class="text-link" @click.stop="copyChart(b,part)">复制图表</button><button class="text-link" @click.stop="remove(b,part)">移除</button></div></div><button class="btn" @click="add(part)">添加内容</button></template>
        </section>
        <p v-if="item.kind==='task'&&!solutions.length" class="muted">尚未提取教材解法。教材没有提供时可留空，不凭空补写。</p>
        <div class="button-row"><button v-if="item.kind==='task'" class="btn" @click="add();to='new';newRole='solution'">添加教材解法</button><button class="btn" @click="dialog='preview'">预览学生题面</button></div>
        <footer class="review-confirm"><label class="check-line"><input type="checkbox" v-model="checked"/>已对照原页核对完整内容、用途与重绘结果</label><button class="btn primary" :disabled="!!storageError" @click="confirmContent">核对完成，进入模型匹配</button></footer>
      </template>
      <template v-else-if="modelEditor"><button class="text-link" @click="modelEditor=null">← 返回当前内容的匹配</button><p class="muted">沿用领域管理编辑器，保存会修改公共领域定义；不改写教材原文。</p><TaskWorkspace v-if="modelEditor.kind==='task'" :key="modelEditor.id+modelEditor.tab" :domain-id="draft.book.domainId" :object-id="modelEditor.id" :tab="modelEditor.tab" @saved="modelSaved" @open="openModel" @back="modelEditor=null"/><MethodWorkspace v-else-if="modelEditor.kind==='solution'" :key="modelEditor.id" :domain-id="draft.book.domainId" :object-id="modelEditor.id" @saved="modelSaved" @open="openModel" @back="modelEditor=null"/><KnowledgeWorkspace v-else :key="modelEditor.id" :domain-id="draft.book.domainId" :object-id="modelEditor.id" @saved="modelSaved" @open="openModel" @back="modelEditor=null"/></template>
      <template v-else><p v-if="!contentReviewed(item)" class="callout amber">本项内容尚未核对，或已有修改。旧选择保留供参考，请先完成核对。</p><p class="muted">匹配当前领域中已有的定义。实例编号和出处自动维护，KC通过方法汇总。</p>
        <table class="data-table match-table"><thead><tr><th>已核对内容</th><th>领域定义</th><th>操作</th></tr></thead><tbody><tr v-for="p in targetRows(item)" :key="p.id"><td>{{p.name}}<small>{{p.role==='question'?'Task':p.role==='solution'?'Solution':'KnowledgeComponent'}}</small></td><td>{{mappedName(p)}}<small v-if="!p.templateId&&suggested(p)">样例建议：{{suggested(p)!.name}}</small></td><td><button class="text-link" :disabled="!contentReviewed(item)" @click="match(p)">{{p.templateId?'查看／更换':'选择并核对'}}</button></td></tr></tbody></table>
        <section v-if="currentTask?.parameters.length" class="parameters"><h4>本题与模板参数的对应</h4><label v-for="parameter in currentTask.parameters.filter(p=>p.role==='题目已给定')" :key="parameter.symbol">{{parameter.symbol}} · {{parameter.name}}<input v-model="item.parts.find(p=>p.role==='question')!.parameters[parameter.symbol]" :disabled="!contentReviewed(item)" @input="item.matched=''"/></label><p class="muted">根据已核对题面填写，不修改模板定义。</p></section>
        <details v-if="currentTask"><summary>方法及汇总的 KC</summary><ul><li v-for="m in domainData.methods.filter(m=>m.domainId===draft.book.domainId&&currentTask!.methods.includes(m.id))" :key="m.id">{{m.name}}</li></ul><p>{{collectKnowledge(currentTask.methods,draft.book.domainId).rows.map(r=>r.knowledge.name).join('、')||'当前方法尚无KC关联，请在领域定义中补齐'}}</p><button class="text-link" @click="openModel('task',currentTask!.id,'methods')">查看任务与方法关联</button></details>
        <p v-if="!solutions.length&&item.kind==='task'" class="muted">本项没有教材解法实例。任务中的方法定义仍保留，不将它伪装成教材原有解法。</p>
        <footer class="review-confirm"><div class="button-row"><button class="btn" @click="emit('stage','semantic')">返回内容核对</button><button class="btn primary" :disabled="!contentReviewed(item)||!!storageError" @click="saveMatch">保存模型关联</button></div><p v-if="mappingConfirmed(item,draft.book.domainId)" class="callout">模型已关联。尚未应用给学生，课程准备和教学评价条件另行检查。</p></footer>
      </template>
    </section>
  </div><div v-else class="panel"><p>当前没有提取内容。原件保留，可以添加漏识别题目或知识表述。</p><button class="btn" @click="addItem">添加内容项</button></div>
  <ReviewBlockEditor v-if="editor" :value="editor.block" :pages="state.pages" :case-id="item.id" @save="saveBlock" @close="editor=null"/>
  <WorkbenchDialog v-if="dialog" :title="({add:'添加内容',move:'移动内容',split:'拆分教材解法',rename:'修改名称',newItem:'添加漏识别内容项',preview:'学生看到的题面',history:'原始提取与修改记录',mapping:'确认领域匹配'})[dialog]" :wide="['split','preview','history','mapping'].includes(dialog)" @close="dialog='';error=''">
    <p v-if="error" class="callout danger" role="alert">{{error}}</p>
    <template v-if="dialog==='add'||dialog==='move'"><label>所属内容<select v-model="to"><option value="">请选择</option><option v-for="p in item.parts.filter(p=>dialog==='add'||p.id!==from)" :key="p.id" :value="p.id">{{p.name}}</option><option value="new">新增一份内容</option></select></label><template v-if="to==='new'"><label>用途<select v-model="newRole"><option value="solution">教材解法</option><option value="answer">教材答案</option><option value="note">教材旁注（不进入题面）</option><option value="knowledge">知识表述</option></select></label><label>名称<input v-model="name" :placeholder="roles[newRole]"/></label></template><label v-if="dialog==='add'">内容形式<select v-model="type"><option v-for="(label,key) in blockNames" :key="key" :value="key">{{label}}</option></select></label><p class="muted">题面仅放给定条件和作答对象。解法、答案和提示单独保存。</p><footer class="dialog-footer"><button class="btn" @click="dialog=''">取消</button><button class="btn primary" :disabled="!to" @click="dialog==='add'?createBlock():applyMove()">{{dialog==='add'?'填写内容':'确认移动'}}</button></footer></template>
    <template v-else-if="dialog==='split'"><p>选出属于另一种解法的内容，移到新解法。整段混在一起时，先返回编辑分段。</p><label>新解法名称<input v-model="name"/></label><label v-for="b in selectedPart?.blocks" :key="b.id" class="split-choice"><input type="checkbox" :value="b.id" v-model="chosen"/><div><ReviewBlockView :block="b"/><small>第 {{b.page}} 页</small></div></label><footer class="dialog-footer"><button class="btn" @click="dialog=''">取消</button><button class="btn primary" @click="applySplit">移到新解法</button></footer></template>
    <template v-else-if="dialog==='rename'"><label>名称<input v-model="name"/></label><footer class="dialog-footer"><button class="btn primary" @click="applyRename">保存名称</button></footer></template>
    <template v-else-if="dialog==='newItem'"><label>内容标题<input v-model="name"/></label><label>所属章节<input v-model="chapter" list="review-chapters"/><datalist id="review-chapters"><option v-for="c in chapters" :key="c">{{c}}</option></datalist></label><label>内容类型<select v-model="newKind"><option value="task">题目</option><option value="knowledge">知识表述</option></select></label><footer class="dialog-footer"><button class="btn primary" :disabled="!name.trim()||!chapter.trim()" @click="createItem">创建并补入内容</button></footer></template>
    <template v-else-if="dialog==='preview'"><p v-if="!contentReviewed(item)" class="callout amber">核对中的预览，不代表已可供学生使用。</p><section data-testid="review-student-preview"><template v-for="p in item.parts.filter(p=>p.role==='question')" :key="p.id"><ReviewBlockView v-for="b in p.blocks" :key="b.id" :block="b"/></template></section><p class="muted">解法、教材答案和旁注不在题面中。</p></template>
    <template v-else-if="dialog==='history'"><details><summary>初始提取（保持原样）</summary><section v-for="p in item.original" :key="p.id"><h4>{{p.name}}</h4><ReviewBlockView v-for="b in p.blocks" :key="b.id" :block="b"/></section></details><p v-if="!item.history.length">尚无内容修改。</p><details v-for="(h,index) in item.history" :key="index"><summary>{{h.at}} · {{h.action}}</summary><div class="history-grid"><section v-for="(parts,label) in {修改前:h.before,修改后:h.after}" :key="label"><h4>{{label}}</h4><div v-for="p in parts" :key="p.id"><b>{{p.name}}</b><ReviewBlockView v-for="b in p.blocks" :key="b.id" :block="b"/></div></section></div></details></template>
    <template v-else-if="dialog==='mapping'&&activeMatch"><p>{{activeMatch.name}} · 只选择当前领域的定义</p><label>查找已有定义<input v-model="query"/></label><label>已有定义<select v-model="selectedDefinition"><option value="">请选择</option><option v-for="d in modelOptions" :key="d.id" :value="d.id">{{d.name}}</option></select></label><template v-if="definition"><p><strong>{{definition.name}}</strong> · v{{definition.version}}</p><p>{{'goal' in definition?definition.goal:definition.description}}</p><p>{{'relations' in definition?definition.relations:definition.conditions}}</p><p v-if="suggested(activeMatch)?.id===definition.id" class="callout">固定样例建议（mock）：请对照当前任务要求和方法步骤确认。此处不运行自动语义归类。</p><button class="text-link" @click="openModel(kindFor(activeMatch),definition!.id)">查看／编辑完整定义</button></template><p v-else class="muted">没有合适定义可新建。方法定义还必须关联到当前 Task 才能选用。</p><footer class="dialog-footer"><button class="btn" @click="openModel(kindFor(activeMatch))">新建缺少的定义</button><button class="btn" @click="dialog=''">暂不处理</button><button class="btn primary" :disabled="!definition" @click="useDefinition">确认选用</button></footer></template>
  </WorkbenchDialog>
</section></template>
<style scoped>.review-header{display:flex;align-items:start;justify-content:space-between;gap:15px;margin-bottom:14px}.review-header h3{margin-bottom:3px}.review-header p{margin:3px 0}.review-layout{display:grid;grid-template-columns:160px minmax(260px,.85fr) minmax(360px,1.15fr);gap:14px;align-items:start}.review-layout .panel{padding:16px}.review-nav,.review-original{position:sticky;top:12px;max-height:86vh;overflow:auto}.review-item{width:100%;border:0;background:transparent;text-align:left;padding:11px 8px;border-radius:6px;color:#3f5c4b;margin-bottom:5px}.review-item.active{background:#e8f3ec;box-shadow:inset 3px 0 #2d6a4f}.review-item small{display:block;font-size:11px;color:#798a80;margin-top:5px}.review-nav h4{font-size:12px;color:#819187;margin:22px 0 10px}.review-nav .btn{margin-top:16px}.review-result h3{font-size:16px}.review-part{border-top:1px solid #e0e9e3;padding:16px 0;margin-top:14px}.part-heading{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap}.part-heading h4{margin:0;font-size:14px}.part-heading .button-row{margin:0}.review-content{padding:9px 10px;margin:8px -5px;border:1px solid transparent;border-radius:5px;cursor:pointer}.review-content.selected{border-color:#bfd4c7;background:#fbfdfb}.content-actions{display:flex;gap:13px;align-items:center;flex-wrap:wrap;margin-top:10px}.content-actions small{color:#85948b;margin-right:auto}.content-actions .text-link{font-size:12px}.review-confirm{border-top:1px solid #dfe8e1;margin-top:24px;padding-top:15px}.review-confirm .btn{white-space:normal}.review-part details summary,details summary{cursor:pointer;color:#2d6a4f;line-height:1.7}.split-choice{display:flex;gap:14px;align-items:start;border-bottom:1px solid #e5ece8;padding:10px}.split-choice>div{flex:1}.split-choice input{margin-top:14px}.history-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.saved-note{font-size:13px;color:#2d6a4f}.parameters{margin:20px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:1220px){.review-layout{grid-template-columns:135px minmax(230px,.8fr) minmax(300px,1.2fr);gap:10px}.review-layout .panel{padding:12px}}@media(max-width:990px){.review-layout{grid-template-columns:130px minmax(0,1fr)}.review-original{position:static;grid-column:2}.review-result{grid-column:2}.review-nav{grid-column:1;grid-row:1/3}}@media(max-width:700px){.review-layout{display:block}.review-nav,.review-original{position:static;max-height:none}.history-grid{grid-template-columns:1fr}}</style>
